import time
from http.server import BaseHTTPRequestHandler, HTTPServer

RATE_LIMIT = 5
WINDOW_SECONDS = 60

# timestamps of requests per client IP
_requests: dict[str, list[float]] = {}


def _prune(timestamps: list[float]) -> list[float]:
    cutoff = time.monotonic() - WINDOW_SECONDS
    return [t for t in timestamps if t >= cutoff]


def _allowed(client_ip: str) -> tuple[bool, float | None]:
    now = time.monotonic()
    timestamps = _requests.setdefault(client_ip, [])
    timestamps = _prune(timestamps)
    if len(timestamps) >= RATE_LIMIT:
        retry_after = int((timestamps[-1] + WINDOW_SECONDS) - now) + 1
        return False, retry_after
    timestamps.append(now)
    return True, None


class Handler(BaseHTTPRequestHandler):
    def _send(self, status: int, body: dict) -> None:
        data = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path.split("?")[0] == "/api/time":
            ok, retry_after = _allowed(self.client_address[0])
            if not ok:
                self._send(429, {"error": "rate limit exceeded"})
                self.send_header("Retry-After", str(retry_after))
                self.end_headers()
                return
            self._send(200, {"now": int(time.time())})
            return
        self._send(404, {"error": "not found"})

    def log_message(self, *args):  # keep output clean
        pass


def main():
    server = HTTPServer(("0.0.0.0", 8000), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()
