export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
  let lastCall = 0;
  let count = 0;

  return function throttled(...args: any[]): void {
    const now = Date.now();
    const sinceLast = now - lastCall;
    const elapsed = sinceLast / windowMs; // windowMs in ms

    // reset window when it's been more than maxPerWindow * windowMs
    if (elapsed >= maxPerWindow) {
      count = 0;
      lastCall = now;
    }

    if (count >= maxPerWindow) {
      // skip excess calls
      return;
    }

    count += 1;
    lastCall = now;
    fn(...args);
  };
}

